use hoonarqube_csharp::{AnalyzerOptions, CsLanguage};
use hoonarqube_csharp::semantic::{ProjectSemanticConfig, ProjectSemanticContext, SourceSnapshot};
use std::io::Read;
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input)?;
    let value: serde_json::Value = serde_json::from_str(&input)?;
    let config: ProjectSemanticConfig = serde_json::from_value(value["config"].clone())?;
    let sources: Vec<SourceSnapshot> = serde_json::from_value(value["sources"].clone())?;
    let context = ProjectSemanticContext::load(&config, &sources);
    let reports: Vec<_> = sources.iter().map(|source| {
        context.analyze_with_context(source.path.clone(), &source.source, CsLanguage::CSharp, &AnalyzerOptions::default())
    }).collect();
    println!("{}", serde_json::to_string(&serde_json::json!({"context": context, "reports": reports}))?);
    Ok(())
}

